eng=tomllib.load(open(GRF+"/english.toml","rb"))
EN={}
for k in GEN:
    v=eng.get(k); EN[k]=v.get("base") if isinstance(v,dict) else v
total=0; summary={}
for f in sorted(os.listdir(GRF)):
    if not f.endswith(".toml") or f=="english.toml": continue
    code=F2C.get(f[:-5])
    if not code: continue
    path=GRF+"/"+f
    t=open(path,"rb").read().decode("utf-8")
    cnt=0
    for k,trans in GEN.items():
        if code not in trans: continue
        tgt=trans[code]
        pat=re.compile(r"(?m)^\["+re.escape(k)+r"\](\r?\n)(\s*base\s*=\s\")(.*?)(\".*)$")
        def repl(m,k=k,tgt=tgt,en=EN[k]):
            if m.group(3)==en: return "["+k+"]"+m.group(1)+m.group(2)+tgt+m.group(4)
            return m.group(0)
        t,n=pat.subn(repl,t); cnt+=n
    if cnt:
        open(path,"wb").write(t.encode("utf-8")); total+=cnt; summary[f[:-5]]=cnt
print("TOTAL grf changes:",total)
for kk,v in sorted(summary.items()): print("  %-22s %d"%(kk,v))
